async function drawVisitor(name,card){if(state.visitorRevealed||!state.drawOrder.includes(name))return;document.querySelectorAll("[data-draw-name]").forEach(x=>x.disabled=true);card.classList.add("is-picked");await new Promise(resolve=>setTimeout(resolve,650));const c=CUSTOMERS.find(x=>x.name===name);state.currentCustomer=CUSTOMERS.indexOf(c);state.currentVisitType=visitTypeFor(c);state.visitorRevealed=true;markCurrentMet();if(state.currentVisitType==="shop")discoverCurrentRequest();save();render();document.querySelector("#visitorDraw").classList.add("draw-revealed");setTimeout(()=>document.querySelector("#visitorDraw").classList.remove("draw-revealed"),1100);document.querySelector(".counter").scrollIntoView({behavior:"smooth",block:"center"})}
function preferenceHints(c){const mood=VISITOR_MOODS[c.name]||{},weatherNames={clear:"晴天",rain:"雨天",fog:"雾天",wind:"有风",storm:"风雪与雷暴"},hints=[];for(const [id,score] of Object.entries(mood.weather||{}))hints.push(`${score>0?"喜欢":"不喜欢"}${weatherNames[id]}`);for(const [id,score] of Object.entries(mood.decor||{})){const d=DECOR.find(x=>x.id===id);if(d)hints.push(`${score>0?"喜欢":"不喜欢"}${d.name}`)}for(const [name,score] of Object.entries(mood.products||{}))hints.push(`${score>0?"喜欢":"不喜欢"}${name}`);return hints.slice(0,3)}
function renderTomorrowForecast(){const forecast=state.tomorrowForecast||generateTomorrowForecast(),day=forecast.day,cal=calendar(day),weekday=["一","二","三","四","五","六","日"][cal.weekday-1];document.querySelector("#tomorrowCalendar").innerHTML=`<div><small>明日</small><strong>第 ${day} 日</strong></div><div><small>星期</small><strong>星期${weekday}</strong></div><div><small>季节与月份</small><strong>${cal.seasonName} · ${cal.seasonName[0]}${["一","二","三"][cal.monthInSeason-1]}月</strong></div><div><small>月相</small><strong>${cal.phaseIcon} ${cal.phaseName}</strong></div>`;document.querySelector("#weatherOptions").innerHTML=forecast.options.map((w,i)=>`<article style="--i:${i}"><span>${w.icon}</span><div><small>可能天气</small><strong>${w.name}</strong><i><b style="width:${w.probability}%"></b></i></div><em>${w.probability}%</em></article>`).join("");const guestSection=document.querySelector("#forecastGuests");if(chapterNumber()<7){guestSection.innerHTML=`<div class="forecast-locked"><b>第七章解锁</b><span>继续经营后，风向针会开始提示明日可能来访的客人。</span></div>`;return}const weatherIds=forecast.options.map(w=>w.id),chapter=chapterForDay(day).id,pool=CUSTOMERS.filter(c=>!employedNames().includes(c.name)&&(c.chapter||1)<=chapter&&activeVisitRules(c).some(rule=>weatherIds.some(id=>ruleMatches(rule,cal,id))));guestSection.innerHTML=`<div class="section-heading"><div><p class="eyebrow">明日门铃</p><h2>可能来访的客人</h2></div><span class="catalog-note">天气尚未确定，名单可能较长</span></div><div class="tomorrow-guests">${pool.map(c=>{const met=state.metCustomers.includes(c.name),hints=chapterNumber()>=8&&met?preferenceHints(c):[];return `<article class="tomorrow-guest ${met?"known":"unknown"}"><span>${met?portraitMarkup(c):"?"}</span><div><small>${met?CATEGORY_NAMES[c.category]:"尚未结识"}</small><strong>${met?c.name:"未知的客人"}</strong>${chapterNumber()<8?`<em>第八章解锁喜好</em>`:hints.length?`<p>${hints.map(h=>`<i>${h}</i>`).join("")}</p>`:""}</div></article>`}).join("")||`<p class="log-empty">风向针没有捕捉到清晰的脚步声。</p>`}</div>`}
function canArrangeProducts(){return chapterNumber()>=6}
function plannedProducts(){return state.plannedDisplayedProducts.filter(name=>count(name)>0&&isDiscovered(name)).slice(0,3)}
function materialUses(name){const products=Object.entries(ITEMS).filter(([,item])=>item.recipe[name]).map(([product])=>product),extras=[];if(name==="寒鸦羽毛")extras.push("购买看店黑猫","部分员工周薪");return [...products,...extras]}
function materialGuide(name){const rules=GATHER_RULES.filter(r=>r.item===name),sources=rules.map(r=>{const loc=WORLD_LOCATIONS.find(l=>l.id===r.location);return `${loc?.icon||"⌖"}${loc?.name||r.location} · ${r.hint} · ${r.rarity}`}).join(" / "),uses=materialUses(name);return `${sources}${uses.length?`｜可用于：${uses.join("、")}`:""}`}
function itemDifficulty(d){const ingredients=Object.values(d.recipe).reduce((n,q)=>n+q,0),rare=Object.keys(d.recipe).filter(name=>GATHER_RULES.find(r=>r.item===name)?.rarity==="稀有").length;return rare||ingredients>=5?"困难":ingredients>=4?"进阶":"基础"}
function inventoryCard(name,d,isProduct=false){const q=count(name),shown=plannedProducts().includes(name),full=plannedProducts().length>=3,canArrange=canArrangeProducts(),craftable=isProduct&&canCraft(name),canShelfCraft=chapterNumber()>=4&&craftable,guide=isProduct?`制作难度 · ${itemDifficulty(d)} · ${Object.entries(d.recipe).map(([n,a])=>`${n}×${a}`).join(" + ")}`:materialGuide(name),kind=isProduct?"product":d.category;return `<article class="item ${q?"":"empty"} ${shown?"displayed":""}" data-kind="${kind}" data-owned="${q>0}" data-craftable="${craftable}"><span class="item-count"><small>库存</small>${q}</span><span class="item-icon">${d.icon}</span><span class="item-name">${name}</span><span class="item-note">${d.note}</span><details class="item-details"><summary>${isProduct?"配方与难度":"来源与用途"}</summary><span class="item-source">${guide}</span></details>${isProduct?`<div class="item-actions"><button class="display-toggle shelf-craft" data-shelf-craft="${name}" ${canShelfCraft?"":"disabled"}>${chapterNumber()<4?"第四章解锁制作":craftable?"制作一件":"材料不足"}</button><button class="display-toggle" data-display="${name}" ${!canArrange||(!shown&&(q<1||full))?"disabled":""}>${chapterNumber()<6?"第六章解锁展示":shown?"从明日柜台收起":"明日摆到柜台"}</button></div>`:""}</article>`}
function renderInventory(){state.plannedDisplayedProducts=plannedProducts();const products=Object.entries(ITEMS).filter(([name])=>isDiscovered(name)),shown=plannedProducts(),canArrange=canArrangeProducts(),shelf=document.querySelector("#displayShelf");shelf.classList.toggle("locked",!canArrange);document.querySelector("#displayShelfHint").textContent=chapterNumber()<6?"第六章解锁成品展示":"随时调整 · 下一天开始影响来客";document.querySelector("#displayedProducts").innerHTML=shown.length?shown.map(name=>`<span><b>${ITEMS[name].icon}</b>${name}<button data-display="${name}" aria-label="收起${name}" ${canArrange?"":"disabled"}>×</button></span>`).join("")+`<small>${shown.length} / 3 · 明日方案</small>`:`<em>明日尚未展示任何成品 · 0 / 3</em>`;const productSection=`<section class="inventory-group products"><header><div><p class="eyebrow">FINISHED GOODS</p><h2>已发现的奇异商品</h2></div><span>${products.length} / ${Object.keys(ITEMS).length} 种配方已发现</span></header><div class="inventory-grid-inner">${products.map(([n,d])=>inventoryCard(n,d,true)).join("")}</div></section>`;const materialSections=Object.entries(MATERIAL_GROUPS).map(([key,group])=>{const entries=Object.entries(MATERIALS).filter(([,d])=>d.category===key);return `<section class="inventory-group" style="--group-color:${group.color}"><header><div><p class="eyebrow">${key.toUpperCase()}</p><h2>${group.name}</h2></div><span>${group.note}</span></header><div class="inventory-grid-inner">${entries.map(([n,d])=>inventoryCard(n,d)).join("")}</div></section>`}).join("");document.querySelector("#inventoryGrid").innerHTML=productSection+materialSections;document.querySelectorAll("[data-display]").forEach(b=>b.addEventListener("click",()=>toggleProductDisplay(b.dataset.display)));document.querySelectorAll("[data-shelf-craft]").forEach(b=>b.addEventListener("click",()=>craftFromShelf(b.dataset.shelfCraft)))}
function toggleProductDisplay(name){if(!canArrangeProducts())return;const shown=state.plannedDisplayedProducts.includes(name);if(shown)state.plannedDisplayedProducts=state.plannedDisplayedProducts.filter(n=>n!==name);else if(count(name)>0&&state.plannedDisplayedProducts.length<3)state.plannedDisplayedProducts.push(name);save();render()}
function craftFromShelf(name){if(chapterNumber()<4||!canCraft(name))return;for(const [material,amount] of Object.entries(ITEMS[name].recipe))state.inventory[material]-=amount;state.inventory[name]=(state.inventory[name]||0)+1;save();render();pulseClass(`[data-shelf-craft="${name}"]`,"crafted-button",650)}
function renderQuickInventory(){const entries=[...Object.entries(ITEMS).filter(([n])=>isDiscovered(n)),...Object.entries(MATERIALS)].filter(([n])=>count(n)>0),total=entries.reduce((n,[name])=>n+count(name),0);document.querySelector("#quickInventoryCount").textContent=`${total} 件库存`;document.querySelector("#quickInventory").innerHTML=entries.length?`<div class="quick-grid">${entries.map(([name,d])=>`<span class="quick-item"><b>${d.icon}</b><em>${name}</em><small>×${count(name)}</small></span>`).join("")}</div><button class="text-button quick-more" data-page="inventory">查看完整货架 →</button>`:`<p class="quick-empty">货架上暂时空空如也。</p>`;document.querySelector("#quickInventory [data-page]")?.addEventListener("click",()=>showPage("inventory"))}
function scheduleIntel(c,favor){const chips=[],base=(VISIT_RULES[c.name]||[]).filter(rule=>(rule.favor||0)===0),seasons={spring:"春季",summer:"夏季",autumn:"秋季",winter:"冬季"},weather={clear:"晴天",rain:"雨天",fog:"雾天",wind:"有风",storm:"雷暴或风雪"},moons={new:"新月",waxing:"盈月",full:"满月",waning:"亏月"},weekdays=["一","二","三","四","五","六","日"];if(favor>=1){const before=chips.length;for(const rule of base){if(rule.season)chips.push(`季节：${rule.season.map(x=>seasons[x]).join("、")}`);if(rule.month)chips.push(`月份：每季第${rule.month.join("、")}月`)}if(chips.length===before)chips.push("季节：没有固定季节") }if(favor>=2){const before=chips.length;for(const rule of base)if(rule.weekday)chips.push(`星期：${rule.weekday.map(x=>"周"+weekdays[x-1]).join("、")}`);if(chips.length===before)chips.push("星期：没有固定星期") }if(favor>=3){const before=chips.length;for(const rule of base){if(rule.weather)chips.push(`天气：${rule.weather.map(x=>weather[x]).join("、")}`);if(rule.moon)chips.push(`月相：${rule.moon.map(x=>moons[x]).join("、")}`)}if(chips.length===before)chips.push("环境：没有固定天气或月相") }if(favor>=4){const before=chips.length;for(const rule of (VISIT_RULES[c.name]||[]).filter(rule=>(rule.favor||0)>0))chips.push(`追加：${rule.label}`);if(chips.length===before)chips.push("追加：暂时没有新的来访窗口") }return [...new Set(chips)]}
function visitorRarity(c){return c.chapter>=3?"稀有":c.chapter===2?"少见":"常见"}
function preferenceLabels(c,positive=true){const config=VISITOR_MOODS[c.name]||{},sign=positive?1:-1,labels=[],weather={clear:"晴天",rain:"雨天",fog:"雾天",wind:"有风",storm:"雷暴或风雪"};for(const [id,score] of Object.entries(config.weather||{}))if(Math.sign(score)===sign)labels.push(`天气 · ${weather[id]}`);for(const [id,score] of Object.entries(config.decor||{})){const d=DECOR.find(x=>x.id===id);if(d&&Math.sign(score)===sign)labels.push(`${d.icon} ${d.name}`)}for(const [name,score] of Object.entries(config.products||{}))if(Math.sign(score)===sign)labels.push(`${ITEMS[name].icon} ${name}`);return labels}
function relationshipHearts(favor){return `<div class="ledger-hearts" aria-label="好感 ${favor}/10">${Array.from({length:5},(_,i)=>{const points=favor-i*2,kind=points>=2?"full":points===1?"half":"empty";return `<i class="${kind}" aria-hidden="true">♥</i>`}).join("")}<b>${favor}/10</b></div>`}
function relationshipCard(c){const locked=c.chapter>chapterNumber(),r=relation(c.name),met=state.metCustomers.includes(c.name),employee=state.employees.find(e=>e.name===c.name),applied=state.applications[c.name],level=r.favor>=8?"知己":r.favor>=4?"熟客":r.favor?"相识":"初见";if(locked)return `<article class="relation-card locked"><span class="relation-icon">⌛</span><div class="relation-main"><span class="tag">第 ${c.chapter} 章解锁</span><h3>尚未写下的名字</h3><p>故事尚未抵达。</p></div></article>`;if(!met)return `<article class="relation-card unknown"><span class="relation-icon">?</span><div class="relation-main"><span class="tag">${CATEGORY_NAMES[c.category]}</span><h3>未知来客</h3><p>初次见面后才会记录。</p></div></article>`;const intel=scheduleIntel(c,r.favor),likes=r.favor>=6?preferenceLabels(c,true):[],dislikes=r.favor>=7?preferenceLabels(c,false):[];return `<article class="relation-card ${r.favor>=8?"bonded":""}"><span class="relation-icon">${portraitMarkup(c)}</span><div class="relation-main"><span class="tag">${c.kind}</span><h3>${c.name}</h3>${relationshipHearts(r.favor)}<p class="relation-stats"><b>${level}</b><span>来访 ${r.visits}</span><span>成交 ${r.deals}</span></p><details class="relation-details"><summary>查看资料 <span>⌄</span></summary><div class="visit-schedule">${intel.length?intel.map(text=>`<span class="schedule-chip active">${text}</span>`).join(""):`<span class="schedule-chip locked-rule">好感 1 后解锁来访规律</span>`}</div>${r.favor>=5?`<div class="visitor-rarity rarity-${c.chapter}">✦ ${visitorRarity(c)}</div>`:""}${r.favor>=6?`<div class="preference-row likes"><b>喜欢</b>${likes.map(x=>`<span>${x}</span>`).join("")}</div>`:""}${r.favor>=7?`<div class="preference-row dislikes"><b>不喜欢</b>${dislikes.map(x=>`<span>${x}</span>`).join("")}</div>`:""}${r.favor>=8?`<div class="bond-highlight"><b>✦ 关系高光</b><span>已把小店当作熟悉的归处。</span></div>`:""}${r.favor>=9?`<div class="future-status">◇ ${employee?`在职 · ${employee.role}`:applied?"简历已收入库":"可能递出简历"}</div>`:""}${r.favor>=10?`<div class="max-bond">♥ 羁绊已满</div>`:""}</details></div></article>`}
function renderRelationships(){document.querySelector("#relationshipGrid").innerHTML=Object.entries(CATEGORY_NAMES).map(([key,label],index)=>{const visitors=CUSTOMERS.filter(c=>c.category===key),known=visitors.filter(c=>state.metCustomers.includes(c.name)).length;return `<details class="visitor-group" ${index===0?"open":""}><summary class="visitor-group-summary"><div class="visitor-title"><span class="category-emblem category-${key}" aria-hidden="true"></span><div><p class="eyebrow">${key.toUpperCase()}</p><h2>${label}</h2></div></div><span><b>${known} / ${visitors.length}</b> 已结识 <i>⌄</i></span></summary><div class="relationship-grid-inner">${visitors.map(relationshipCard).join("")}</div></details>`}).join("")}
function renderHistory(){document.querySelector("#historyList").innerHTML=state.history.length?state.history.map(h=>`<div class="history-row"><span class="history-day">第 ${h.day} 日</span><span>${h.story}</span><span class="history-outcome">${h.outcome}</span></div>`).join(""):`<div class="history-row"><span class="history-day">开店前</span><span>你擦亮门上的铜铃，等待第一个故事。</span><span class="history-outcome">尚无记录</span></div>`}
function renderLog(){const met=CUSTOMERS.filter(c=>state.metCustomers.includes(c.name)),appearances=c=>relation(c.name).visits+(!state.resolved&&state.visitorRevealed&&dailyCustomer().name===c.name?1:0),totals=met.reduce((sum,c)=>{const r=relation(c.name);sum.visits+=appearances(c);sum.deals+=r.deals;sum.favor+=r.favor;return sum},{visits:0,deals:0,favor:0}),rate=totals.visits?Math.round(totals.deals/totals.visits*100):0,avg=met.length?(totals.favor/met.length).toFixed(1):"0.0";document.querySelector("#logSummary").innerHTML=`<article><span>📅</span><small>开店时间</small><strong>第 ${state.day} 天</strong><em>走过 ${calendar().month} 个月份</em></article><article><span>🔔</span><small>来客记录</small><strong>${totals.visits} 次</strong><em>结识 ${met.length} / ${CUSTOMERS.length} 位客人</em></article><article><span>🤝</span><small>成功交易</small><strong>${totals.deals} 次</strong><em>成交率 ${rate}%</em></article><article><span>♥</span><small>平均好感</small><strong>${avg}</strong><em>当前共有 ${totals.favor} 点好感</em></article>`;document.querySelector("#guestStats").innerHTML=met.length?met.map(c=>{const r=relation(c.name),visits=appearances(c),success=visits?Math.round(r.deals/visits*100):0;return `<article class="guest-stat"><span class="guest-stat-icon">${portraitMarkup(c)}</span><div><small>${CATEGORY_NAMES[c.category]}</small><strong>${c.name}</strong><em>${c.kind}</em></div><dl><div><dt>出现</dt><dd>${visits}</dd></div><div><dt>成交</dt><dd>${r.deals}</dd></div><div><dt>成功率</dt><dd>${success}%</dd></div><div><dt>好感</dt><dd>${r.favor}/10</dd></div></dl></article>`}).join(""):`<p class="log-empty">门铃还没有留下第一位客人的名字。</p>`}
function costLabel(d){return d.cost.coins?`${d.cost.coins} 枚铜币`:`${d.cost.amount} × ${d.cost.item}`}
function canBuy(d){return d.cost.coins?state.coins>=d.cost.coins:count(d.cost.item)>=d.cost.amount}
function decorScene(d){const scenes={lamp:`<b>${d.icon}</b><i class="lamp-glow"></i>`,plant:`<b>${d.icon}</b><i class="plant-yawn">呼…</i>`,rug:`<i class="rug-star">✦</i><i class="rug-star">·</i><i class="rug-star">✧</i>`,cat:`<b>${d.icon}</b><i class="cat-thought">♪</i>`,clock:`<b>${d.icon}</b><i class="clock-pendulum"></i>`,teaset:`<b>${d.icon}</b><i class="steam steam-one">〰</i><i class="steam steam-two">〰</i>`,clogs:`<b>${d.icon}</b><i class="dutch-spark">✦</i>`,windmill:`<b>${d.icon}</b>`,friesian:`<b>${d.icon}</b><i class="horse-note">♪</i>`,goose:`<b>${d.icon}</b>`};return scenes[d.id]||d.icon}
function renderShop(){const owned=ownedDecor(),planned=DECOR.filter(d=>state.plannedDecor.includes(d.id));document.querySelector("#comfortScore").textContent=planned.reduce((n,d)=>n+d.comfort,0);document.querySelector("#decorStatus").textContent=`随时调整 · 下一天生效 · 已拥有 ${owned.length} 件`;document.querySelector("#decorLayer").innerHTML=planned.map(d=>`<span class="placed-decor decor-${d.id}" title="${d.name}（明日方案）">${decorScene(d)}</span>`).join("");document.querySelector("#decorGrid").innerHTML=DECOR.map(d=>{const bought=state.decor.includes(d.id),placed=state.plannedDecor.includes(d.id);return `<article class="decor-card ${bought?"owned":""} ${placed?"is-placed":""}"><span class="decor-icon">${d.icon}</span><div><h3>${d.name}</h3><p>${d.note}</p><div class="effect-tag">✦ ${d.effect}</div><small>${placed?"已加入明日布置":bought?"已拥有 · 明日不摆出":"温暖度 +"+d.comfort}</small></div>${bought?`<button class="button ${placed?"primary":"ghost"}" data-decor-toggle="${d.id}">${placed?"明日收起来":"明日摆出来"}</button>`:`<button class="button primary" data-buy="${d.id}" ${!canBuy(d)?"disabled":""}>${costLabel(d)}</button>`}</article>`}).join("");document.querySelectorAll("[data-buy]").forEach(b=>b.addEventListener("click",()=>buyDecor(b.dataset.buy)));document.querySelectorAll("[data-decor-toggle]").forEach(b=>b.addEventListener("click",()=>toggleDecor(b.dataset.decorToggle)));renderStaff()}
function toggleDecor(id){if(!state.decor.includes(id))return;state.plannedDecor=state.plannedDecor.includes(id)?state.plannedDecor.filter(x=>x!==id):[...state.plannedDecor,id];save();render()}
function buyDecor(id){const d=DECOR.find(x=>x.id===id);if(!d||state.decor.includes(id)||!canBuy(d))return;if(d.cost.coins)state.coins-=d.cost.coins;else state.inventory[d.cost.item]-=d.cost.amount;state.decor.push(id);save();render();document.querySelector("#noticeLabel").textContent="店铺陈设";document.querySelector("#noticeTitle").textContent=`添置了${d.name}`;document.querySelector("#noticeText").textContent=`${d.note}。物件已经买下，可以随时加入明日布置。`;document.querySelector("#noticeDialog").showModal()}
function vacationLabel(name){const cfg=EMPLOYMENT[name];return `每年第 ${cfg.vacationMonth} 月 · 第 ${cfg.vacationWeek} 周休假`}
function abilityLabels(name){const a=EMPLOYMENT[name].abilities,cats=a.greeter.categories.map(x=>CATEGORY_NAMES[x]).join("、"),maker=!a.maker.enabled?"不能担任制作者":`每日制作 ${a.maker.dailyLimit} 件 · ${a.maker.priority==="rare"?"优先稀有商品":a.maker.priority==="advanced"?"优先高阶商品":"普通顺序"}`,display=!a.display.enabled?"不能担任陈列员":`每日陈列 ${a.display.dailySlots} 件 · ${{forecast:"结合预报与喜好",rare:"优先稀有商品",familiar:"优先常见商品",standard:"普通库存顺序"}[a.display.strategy]}`,places=a.gather.locations.map(id=>WORLD_LOCATIONS.find(l=>l.id===id)?.name).join("、");return [`${a.greeter.label}：${cats}信任 +${a.greeter.strength}，其他客群 +1`,`制作者：${maker}`,`陈列员：${display}`,`采集员：擅长 ${places} · 每时段最多 ${a.gather.yield} 件`]}
function roleOptions(name,current){const a=EMPLOYMENT[name].abilities,roles=[{id:"greeter",label:`迎宾 · ${a.greeter.label}`}];if(a.maker.enabled)roles.push({id:"maker",label:`制作者 · 每日 ${a.maker.dailyLimit} 件`});if(a.display.enabled)roles.push({id:"display",label:`陈列员 · 每日 ${a.display.dailySlots} 件`});roles.push({id:"gather",label:`采集员 · 每时段最多 ${a.gather.yield} 件`});return roles.map(r=>`<option value="${r.id}" ${current===r.id?"selected":""}>${r.label}</option>`).join("")}
function inProtectedVacation(e){return calendar().month===EMPLOYMENT[e.name].vacationMonth}
function renderStaff(){const applications=Object.keys(state.applications).filter(name=>state.applications[name]&&!employedNames().includes(name));document.querySelector("#staffStatus").textContent=`已雇佣 ${state.employees.length} 位 · 无人数上限 · 待聘简历 ${applications.length} 份`;const employees=state.employees.map(e=>{const c=CUSTOMERS.find(x=>x.name===e.name),cfg=EMPLOYMENT[e.name],pending=state.day<(e.startDay||1),away=!pending&&!activeEmployee(e),protectedMonth=inProtectedVacation(e);return `<article class="staff-card employed ${away?"on-leave":""} ${pending?"pending-start":""}"><span class="staff-portrait">${portraitMarkup(c)}</span><div><small>${pending?`第 ${e.startDay} 日 · 周一入职`:away?"本周休假":"在店工作"}</small><h3>${e.name}</h3><p>周薪 ${cfg.weeklySalary} 铜币 · ${vacationLabel(e.name)}</p>${e.debt?`<strong class="wage-debt">欠薪 ${e.debt} 铜币</strong>`:""}<label>分配职位<select data-staff-role="${e.name}"><option value="greeter" ${e.role==="greeter"?"selected":""}>迎宾 · 来客信任 +1</option><option value="maker" ${e.role==="maker"?"selected":""}>制作者 · 自动补货至 2 件</option></select></label>${e.role==="gather"?`<label>采集地区<select data-gather-location="${e.name}">${EMPLOYMENT[e.name].abilities.gather.locations.map(id=>`<option value="${id}" ${(e.gatherLocation||EMPLOYMENT[e.name].abilities.gather.locations[0])===id?"selected":""}>${WORLD_LOCATIONS.find(l=>l.id===id).name}</option>`).join("")}</select></label>`:""}</div><button class="button ghost" data-dismiss="${e.name}" ${protectedMonth?"disabled":""}>${protectedMonth?"休假月不可辞退":"辞退"}</button></article>`}).join("");const resumes=applications.map(name=>{const c=CUSTOMERS.find(x=>x.name===name),cfg=EMPLOYMENT[name];return `<article class="staff-card resume"><span class="staff-portrait">${portraitMarkup(c)}</span><div><small>已收到简历</small><h3>${name}</h3><p>周薪 ${cfg.weeklySalary} 铜币 · ${vacationLabel(name)}</p></div><span class="resume-note">等待下次本人来访确认录用</span></article>`}).join("");document.querySelector("#staffGrid").innerHTML=employees+resumes||`<p class="log-empty">好感达到 9 的熟客，可能会在来访时递出简历。</p>`;document.querySelectorAll("[data-staff-role]").forEach(s=>s.addEventListener("change",()=>assignRole(s.dataset.staffRole,s.value)));document.querySelectorAll("[data-gather-location]").forEach(s=>s.addEventListener("change",()=>assignGatherLocation(s.dataset.gatherLocation,s.value)));document.querySelectorAll("[data-dismiss]").forEach(b=>b.addEventListener("click",()=>dismissEmployee(b.dataset.dismiss)))}
function assignRole(name,role){const e=state.employees.find(x=>x.name===name),a=EMPLOYMENT[name]?.abilities,allowed=role==="greeter"||role==="maker"&&a.maker.enabled||role==="display"&&a.display.enabled||role==="gather";if(e&&allowed){e.role=role;if(role==="gather"&&!e.gatherLocation)e.gatherLocation=a.gather.locations[0];save();render()}}
function assignGatherLocation(name,location){const e=state.employees.find(x=>x.name===name),allowed=EMPLOYMENT[name]?.abilities.gather.locations.includes(location);if(e&&allowed){e.gatherLocation=location;save();render()}}
function dismissEmployee(name){const e=state.employees.find(x=>x.name===name);if(!e||inProtectedVacation(e))return;state.employees=state.employees.filter(x=>x.name!==name);invalidateResume(name);state.history.unshift({day:state.day,story:`${name}离开了迟灯杂货铺。下一份简历的条件会有所调整。`,outcome:"结束雇佣 · 简历失效"});save();render()}
function pulseClass(selector,className,duration=700){const el=document.querySelector(selector);if(!el)return;el.classList.remove(className);void el.offsetWidth;el.classList.add(className);setTimeout(()=>el.classList.remove(className),duration)}
function playDayIntro(){const page=document.querySelector("#page-visitor");page.classList.remove("is-revealing");void page.offsetWidth;page.classList.add("is-revealing");setTimeout(()=>page.classList.remove("is-revealing"),1800)}
function complete(action){const c=dailyCustomer(),rel=relation(c.name),visitType=state.currentVisitType||"shop",cfg=EMPLOYMENT[c.name];let title,text,label,icon="✦",outcome;if(action==="craft"&&visitType==="shop"){for(const [n,q] of Object.entries(ITEMS[c.item].recipe))state.inventory[n]-=q;state.inventory[c.item]=(state.inventory[c.item]||0)+1;save();render();document.querySelector("#availabilityText").textContent="制作完成，继续检查客人的需求数量";pulseClass("#page-visitor","crafting",850);return}rel.visits+=1;if(visitType==="resume"){if(action==="sell"){state.applications[c.name]={receivedDay:state.day};rel.favor=10;title="一份写得很仔细的简历";text=`你收下了${c.name}的简历。下次来访时，可以预付 ${cfg.weeklySalary} 枚铜币的第一周工资并邀请入职。`;outcome="收到简历 · 好感已满";label="简历已收下"}else{title="改日再谈也没有关系";text=`${c.name}收好简历，约定下一次鼓起勇气时再来。`;outcome="暂未收下简历";label="客人离开了"}}else if(visitType==="hire"){if(action==="sell"&&state.coins>=cfg.weeklySalary){state.coins-=cfg.weeklySalary;state.employees.push({name:c.name,role:"greeter",debt:0,nextPayDay:state.day+7,hiredDay:state.day});title="迟灯杂货铺的新店员";text=`你预付了 ${cfg.weeklySalary} 枚铜币。${c.name}从今天起担任迎宾，职位可以随时在“我的小店”调整。`;outcome=`正式入职 · 预付周薪 ${cfg.weeklySalary}`;label="雇佣成功"}else{title="这份简历仍然有效";text=`${c.name}把入职决定留到下一次来访。店里有空位并备好第一周工资后，仍可继续雇佣。`;outcome="暂缓雇佣";label="稍后再决定"}}else if(action==="sell"){const r=reward(c),needed=requestAmount(c);state.inventory[c.item]-=needed;if(state.inventory[c.item]<1)state.displayedProducts=state.displayedProducts.filter(name=>name!==c.item);if(r.type==="coins")state.coins+=r.amount;else state.inventory[r.item]=(state.inventory[r.item]||0)+r.amount;rel.favor=Math.min(10,rel.favor+2);rel.deals+=1;title="门铃轻轻响了两次";text=`${c.name}带着 ${needed} 件${c.item}离开了。最终支付了${r.type==="coins"?r.amount+" 枚铜币":r.amount+" × "+r.item}，你们的好感增加了 2 点。`;outcome=`售出「${c.item}」×${needed} · 好感 +2`;label="交易完成"}else{const loss=chapterNumber()===1?0:1;rel.favor=Math.max(0,rel.favor-loss);title="有些故事不属于今晚";text=`你向${c.name}摇了摇头。客人把故事重新收好，消失在门外的夜色里。`;outcome=chapterNumber()===1?"婉言拒绝 · 新手期不降低好感":"婉言拒绝 · 好感 -1";icon="☾";label="客人离开了"}state.resolved=true;state.history.unshift({day:state.day,story:visitType==="shop"?`${c.name}来寻找${c.item}。`:`${c.name}为店员一事来到店里。`,outcome});save();render();pulseClass("#page-visitor",action==="sell"?"sale-complete":"guest-leaving",800);showDialog(icon,label,title,text)}
function showDialog(icon,label,title,text){if(label==="雇佣成功"){const e=state.employees.find(x=>x.hiredDay===state.day);if(e){label="录用成功";title="录用关系已经确定";text=`第一周工资已经预付。${e.name}会在第 ${e.startDay} 日（周一）正式入职，到岗后才开始提供职位效果。`}}document.querySelector("#dialogIcon").textContent=icon;document.querySelector("#dialogLabel").textContent=label;document.querySelector("#dialogTitle").textContent=title;document.querySelector("#dialogText").textContent=text;document.querySelector("#nextDayButton").innerHTML=state.timeSlot===4?'结束今天，迎接清晨 <span>→</span>':`继续到${TIME_SLOTS[state.timeSlot+1].name} <span>→</span>`;document.querySelector("#resultDialog").showModal()}
function processPayroll(){const kept=[];for(const e of state.employees){if(state.day<e.nextPayDay){kept.push(e);continue}const cfg=EMPLOYMENT[e.name],due=(e.debt||0)+cfg.weeklySalary,paid=Math.min(state.coins,due);state.coins-=paid;e.debt=due-paid;e.nextPayDay+=7;if(!e.debt){kept.push(e);state.history.unshift({day:state.day,story:`为${e.name}支付了下一周工资。`,outcome:`周薪 ${cfg.weeklySalary} 铜币`})}else if(inProtectedVacation(e)){kept.push(e);state.history.unshift({day:state.day,story:`${e.name}正在休假月，未付工资记入欠款。`,outcome:`欠薪 ${e.debt} 铜币`})}else{delete state.applications[e.name];state.history.unshift({day:state.day,story:`${e.name}因工资与欠薪未能结清而离开。`,outcome:"员工离职"})}}state.employees=kept}
function settleVacationDebt(){for(const e of state.employees){if(!e.debt)continue;const cfg=EMPLOYMENT[e.name],before=e.debt;e.debt=payWage(cfg.wage,e.debt);const paid=before-e.debt;if(paid>0)state.history.unshift({day:state.day,story:`库存到账后优先补发了${e.name}的欠薪。`,outcome:`补发 ${paid} ${cfg.wage.type==="coins"?"枚铜币":cfg.wage.item}${e.debt?` · 尚欠 ${e.debt}`:" · 已结清"}`})}}
function resolveReturnedDebt(){settleVacationDebt();state.employees=state.employees.filter(e=>{if(!e.debt||inProtectedVacation(e))return true;invalidateResume(e.name);state.history.unshift({day:state.day,story:`${e.name}休假归来时欠薪仍未补足，因此离开了小店。下一份简历条件将调整。`,outcome:`欠薪 ${e.debt} · 离职`});return false})}
function announceEmployeeStarts(){for(const e of state.employees)if(e.startDay===state.day)state.history.unshift({day:state.day,story:`${e.name}在周一准时来到迟灯杂货铺，正式开始工作。`,outcome:`入职 · ${e.role==="maker"?"制作者":"迎宾"}`})}
function renderEmploymentTerms(c,visitType){const cfg=EMPLOYMENT[c.name],hire=document.querySelector("#hireButton"),candidate=!!state.applications[c.name]&&!employedNames().includes(c.name),revision=(state.employmentRevisions[c.name]||0)+1;hire.hidden=!candidate;if(visitType==="resume"){document.querySelector("#customerStory").textContent=`${c.name}递来第 ${revision} 版简历。周薪是 ${wageLabel(cfg)}；每年第 ${cfg.vacationMonth} 月中的第 ${cfg.vacationWeek} 周休假，休假月不可辞退。工作能力：${abilityLabels(c.name).join("；")}。`;document.querySelector("#paymentOffer").textContent=`第 ${revision} 版 · 期望周薪 ${wageLabel(cfg)}`}else if(candidate){const full=false,afford=canPayWage(cfg);hire.textContent=`支付 ${wageLabel(cfg)}并录用`;hire.disabled=state.resolved||full||!afford;document.querySelector("#availabilityText").textContent+=full?" · 简历有效，但员工名额已满":afford?" · 简历库中已有此人，可交易或录用":` · 简历仍有效，当前付不起 ${wageLabel(cfg)}`}else if(isAdvanced(c.name))document.querySelector("#availabilityText").textContent+=` · 高好感熟客会永久提高支付`}
function completeRecruitment(action){const c=dailyCustomer(),rel=relation(c.name),cfg=EMPLOYMENT[c.name],type=state.currentVisitType;let title,text,label,outcome,icon="✦";rel.visits+=1;if(type==="resume"){if(action==="sell"){state.applications[c.name]={receivedDay:state.day};rel.favor=10;title="一份写得很仔细的简历";text=`你收下了${c.name}的简历。下次来访时，可以预付 ${wageLabel(cfg)}并确认录用。`;outcome="收到简历 · 好感已满";label="简历已收下"}else{state.paymentBoosts[c.name]=true;title="改日再谈也没有关系";text=`${c.name}收好简历。作为没有被录用后的诚意，下次购物来访会提高支付。`;outcome="暂未收下简历 · 下次提高报酬";label="客人离开了"}}else if(action==="sell"&&canPayWage(cfg)){payWage(cfg.wage,cfg.wage.amount);state.employees.push({name:c.name,role:"greeter",debt:0,nextPayDay:state.day+7,hiredDay:state.day});save();const e=state.employees.find(x=>x.name===c.name);title="录用关系已经确定";text=`你预付了 ${wageLabel(cfg)}。${c.name}会在第 ${e.startDay} 日（周一）正式入职。`;outcome=`确认录用 · 第 ${e.startDay} 日周一入职`;label="录用成功"}else{state.paymentBoosts[c.name]=true;title="这份简历仍然有效";text=`${c.name}把录用决定留到以后。下次会先作为购物客人回来，并提高支付。`;outcome="暂缓录用 · 下次提高报酬";label="稍后再决定"}state.resolved=true;state.history.unshift({day:state.day,story:`${c.name}为店员一事来到店里。`,outcome});save();render();showDialog(icon,label,title,text)}
function completeRecruitmentV2(action){const c=dailyCustomer(),rel=relation(c.name),cfg=EMPLOYMENT[c.name],type=state.currentVisitType;let title,text,label,outcome,icon="✦";rel.visits+=1;if(type==="resume"){if(action==="sell"){state.applications[c.name]={receivedDay:state.day};rel.favor=Math.max(10,rel.favor);title="一份写得很仔细的简历";text=`你收下了${c.name}的简历。下一次本人来访时，可以预付 ${wageLabel(cfg)}并确认录用。`;outcome="收到简历 · 获得一次录用机会";label="简历已收下"}else{delete state.applications[c.name];title="改日再谈也没有关系";text=`${c.name}收好简历。只要还没有入职，以后每次来访仍可能重新递出。`;outcome="暂未收下简历";label="客人离开了"}}else if(action==="sell"&&canPayWage(cfg)){payWage(cfg.wage,cfg.wage.amount);state.employees.push({name:c.name,role:"greeter",debt:0,nextPayDay:state.day+7,hiredDay:state.day});delete state.applications[c.name];save();const e=state.employees.find(x=>x.name===c.name);title="录用关系已经确定";text=`你预付了 ${wageLabel(cfg)}。${c.name}会在第 ${e.startDay} 日（周一）正式入职。`;outcome=`确认录用 · 第 ${e.startDay} 日周一入职`;label="录用成功"}else{delete state.applications[c.name];title="这次没有确定录用";text=`本次录用机会已经结束。${c.name}以后每次来访仍可能重新递出简历；没有递简历时会作为高价熟客购物。`;outcome="未录用 · 需要重新投递简历";label="稍后再决定"}state.resolved=true;state.history.unshift({day:state.day,story:`${c.name}为店员一事来到店里。`,outcome});save();render();showDialog(icon,label,title,text)}
completeRecruitment=completeRecruitmentV2;
function hireCandidate(){const c=dailyCustomer(),cfg=EMPLOYMENT[c.name],rel=relation(c.name);if(!state.applications[c.name]||!canPayWage(cfg)||state.resolved)return;payWage(cfg.wage,cfg.wage.amount);state.employees.push({name:c.name,role:"greeter",debt:0,nextPayDay:state.day+7,hiredDay:state.day});rel.visits+=1;save();const e=state.employees.find(x=>x.name===c.name),outcome=`确认录用 · 第 ${e.startDay} 日周一入职`;state.resolved=true;state.history.unshift({day:state.day,story:`${c.name}带着仍在简历库里的简历来到店里。`,outcome});save();render();showDialog("✦","录用成功","录用关系已经确定",`你预付了 ${wageLabel(cfg)}。${c.name}会在第 ${e.startDay} 日（周一）正式入职。旧简历会保留到将来辞退或欠薪离职时。`)}
