processPayroll=function(){const kept=[];for(const e of state.employees){if(state.day<e.nextPayDay){kept.push(e);continue}const cfg=EMPLOYMENT[e.name],due=(e.debt||0)+cfg.wage.amount;e.debt=payWage(cfg.wage,due);e.nextPayDay+=7;if(!e.debt){kept.push(e);state.history.unshift({day:state.day,story:`为${e.name}支付了下一周工资。`,outcome:`周薪 ${wageLabel(cfg)}`})}else if(inProtectedVacation(e)){kept.push(e);state.history.unshift({day:state.day,story:`${e.name}正在休假月，未付工资记入欠款。`,outcome:`欠薪 ${e.debt} ${cfg.wage.type==="coins"?"铜币":cfg.wage.item}`})}else{delete state.applications[e.name];state.history.unshift({day:state.day,story:`${e.name}因工资与欠薪未能结清而离开。`,outcome:"员工离职"})}}state.employees=kept};
settleVacationDebt=function(){for(const e of state.employees){if(!e.debt)continue;const cfg=EMPLOYMENT[e.name],before=e.debt;e.debt=payWage(cfg.wage,e.debt);const paid=before-e.debt;if(paid>0)state.history.unshift({day:state.day,story:`库存到账后优先补发了${e.name}的欠薪。`,outcome:`补发 ${paid} ${cfg.wage.type==="coins"?"枚铜币":cfg.wage.item}${e.debt?` · 尚欠 ${e.debt}`:" · 已结清"}`})}};
processPayroll=function(){const kept=[],entries=[],isMonday=calendar().weekday===1;for(const e of state.employees){const cfg=EMPLOYMENT[e.name],pending=state.day<(e.startDay||1),due=state.day>=e.nextPayDay;let paid=0,status=pending?`等待第 ${e.startDay} 日入职`:"首周工资此前已预付";if(due){const totalDue=(e.debt||0)+cfg.wage.amount,remaining=payWage(cfg.wage,totalDue);paid=totalDue-remaining;e.debt=remaining;e.nextPayDay+=7;if(!remaining){kept.push(e);status="下周工资已付清";state.history.unshift({day:state.day,story:`为${e.name}支付了下一周工资。`,outcome:`周薪 ${wageLabel(cfg)}`})}else if(inProtectedVacation(e)){kept.push(e);status=`休假月欠薪 ${remaining}`;state.history.unshift({day:state.day,story:`${e.name}正在休假月，未付工资记入欠款。`,outcome:`欠薪 ${remaining} ${cfg.wage.type==="coins"?"铜币":cfg.wage.item}`})}else{invalidateResume(e.name);status="工资未结清 · 已离职";state.history.unshift({day:state.day,story:`${e.name}因工资未能结清而离开，旧简历失效。`,outcome:"员工离职"})}}else kept.push(e);if(isMonday)entries.push({name:e.name,role:e.role,wage:wageLabel(cfg),paid,unit:cfg.wage.type==="coins"?"枚铜币":cfg.wage.item,status,debt:e.debt||0,vacation:`第 ${cfg.vacationMonth} 月第 ${cfg.vacationWeek} 周`})}state.employees=kept;if(isMonday)state.weeklySummary={day:state.day,week:Math.floor((state.day-1)/7)+1,acknowledged:false,entries}}
function renderWeeklySummary(){const box=document.querySelector("#weeklySummaryPage"),summary=state.weeklySummary;if(!summary||summary.day!==state.day||summary.acknowledged){box.hidden=true;return}box.hidden=false;document.querySelector("#weeklySummaryTitle").textContent=`第 ${summary.week} 周 · 下周工资账目`;const paid=summary.entries.filter(e=>e.paid>0);document.querySelector("#weeklySummaryIntro").textContent=paid.length?`本次为 ${paid.length} 位员工支付了下周工资。每种资源分别记账如下。`:summary.entries.length?"本周没有新的扣款；首周工资可能已在录用时预付。":"本周还没有员工工资需要结算。";document.querySelector("#weeklyStaffList").innerHTML=summary.entries.length?summary.entries.map(e=>`<article><div><strong>${e.name}</strong><small>${e.role==="maker"?"制作者":e.role==="display"?"陈列员":e.role==="gather"?"采集员":"迎宾"} · 休假 ${e.vacation}</small></div><p><b>${e.paid?`本次支付 ${e.paid} ${e.unit}`:"本次未扣款"}</b><span>约定周薪 ${e.wage}</span><em>${e.status}${e.debt?` · 尚欠 ${e.debt} ${e.unit}`:""}</em></p></article>`).join(""):`<p class="log-empty">店里还没有员工，账本这一页是空的。</p>`}
function closeWeeklySummary(){if(state.weeklySummary){state.weeklySummary.acknowledged=true;save();renderWeeklySummary()}}
function autoCraftByStaff(){if(!state.employees.some(e=>e.role==="maker"&&activeEmployee(e)))return;const made=[];for(const [name] of Object.entries(ITEMS)){if(!isDiscovered(name))continue;while(count(name)<2&&canCraft(name)){for(const [material,amount] of Object.entries(ITEMS[name].recipe))state.inventory[material]-=amount;state.inventory[name]=(state.inventory[name]||0)+1;made.push(name)}}if(made.length)state.history.unshift({day:state.day,story:`制作者检查材料后，自动完成了${made.join("、")}。`,outcome:"店员自动制作"})}
autoCraftByStaff=function(){const workers=state.employees.filter(e=>e.role==="maker"&&activeEmployee(e)),made=[];for(const e of workers){const a=EMPLOYMENT[e.name].abilities.maker,pool=Object.keys(ITEMS).filter(name=>isDiscovered(name)&&count(name)<2&&canCraft(name));pool.sort((x,y)=>a.priority==="rare"?(ITEMS[y].chapter-ITEMS[x].chapter):a.priority==="advanced"?(Object.keys(ITEMS[y].recipe).length-Object.keys(ITEMS[x].recipe).length):0);let remaining=a.dailyLimit;while(remaining>0){const name=pool.find(n=>count(n)<2&&canCraft(n));if(!name)break;for(const [material,amount] of Object.entries(ITEMS[name].recipe))state.inventory[material]-=amount;state.inventory[name]=(state.inventory[name]||0)+1;made.push(`${e.name}制作${name}`);remaining--}}if(made.length)state.history.unshift({day:state.day,story:made.join("、")+"。",outcome:"店员自动制作"})}
function autoArrangeForTomorrow(){const clerks=state.employees.filter(e=>e.role==="display"&&activeEmployee(e,state.day+1));if(!clerks.length)return;const clerk=clerks[0],a=EMPLOYMENT[clerk.name].abilities.display,owned=Object.keys(ITEMS).filter(name=>isDiscovered(name)&&count(name)>0),forecast=state.tomorrowForecast,cal=calendar(state.day+1),weatherIds=forecast?.options?.map(w=>w.id)||[],guests=CUSTOMERS.filter(c=>!employedNames().includes(c.name)&&(c.chapter||1)<=chapterForDay(state.day+1).id&&activeVisitRules(c).some(rule=>weatherIds.some(id=>ruleMatches(rule,cal,id))));const score=name=>{if(a.strategy==="rare")return ITEMS[name].chapter*20;if(a.strategy==="familiar")return (4-ITEMS[name].chapter)*20;if(a.strategy==="forecast")return guests.reduce((n,c)=>n+(VISITOR_MOODS[c.name]?.products?.[name]||0),0)*20+ITEMS[name].chapter;return owned.indexOf(name)*-1};state.plannedDisplayedProducts=owned.sort((x,y)=>score(y)-score(x)).slice(0,Math.min(3,a.dailySlots));state.history.unshift({day:state.day,story:`${clerk.name}依据${a.strategy==="forecast"?"明日预报":"自己的陈列习惯"}重新安排了柜台。`,outcome:`自动陈列 ${state.plannedDisplayedProducts.join("、")||"空柜台"}`})}
function renderDaySummary(){const box=document.querySelector("#daySummaryPage");if(!state.dailySummaryOpen){box.hidden=true;return}box.hidden=false;const actions=state.dailyActions||[],gathered=actions.flatMap(a=>a.items||[]),gatheredCount=gathered.reduce((n,item)=>n+item.amount,0),visitorCount=actions.filter(a=>a.type==="shop"&&a.title.includes("·")).length+actions.reduce((n,a)=>n+(a.staffVisitors||0),0),coinDelta=state.coins-(state.dayStartCoins??state.coins);document.querySelector("#daySummaryTitle").textContent=`第 ${state.day} 日 · ${calendar().seasonName}手记`;document.querySelector("#daySummaryIntro").textContent=`${state.weather.icon} ${state.weather.name} · ${calendar().phaseName}。五个时段都已经过去，小店的灯在深夜安静下来。`;document.querySelector("#daySummaryStats").innerHTML=`<span><small>营业来客</small><strong>${visitorCount} 位</strong></span><span><small>外出次数</small><strong>${actions.filter(a=>a.type==="gather").length} 次</strong></span><span><small>采集材料</small><strong>${gatheredCount} 件</strong></span><span><small>铜币变化</small><strong>${coinDelta>=0?"+":""}${coinDelta}</strong></span>`;document.querySelector("#dayTimeline").innerHTML=TIME_SLOTS.map((slot,i)=>{const action=actions[i]||{time:slot.name,icon:"…",title:"没有留下记录",outcome:"这一段时间静静过去"};return `<article><span>${action.icon}</span><div><small>${slot.icon} ${slot.name}</small><strong>${action.title}</strong><em>${action.outcome}</em></div></article>`}).join("")}
function capturePendingPeriod(){if(!state.pendingPeriodAction)return;const action=state.pendingPeriodAction,latest=state.history.find(entry=>entry.day===state.day&&(!action.visitor||entry.story.includes(action.visitor)));state.dailyActions.push({...action,outcome:latest?.outcome||"来访结束"});state.pendingPeriodAction=null}
function runEmployeePeriod(playerAway=false){const notes=[],staffItems=[],gatherers=state.employees.filter(e=>e.role==="gather"&&activeEmployee(e));for(const employee of gatherers){const ability=EMPLOYMENT[employee.name].abilities.gather,location=employee.gatherLocation||ability.locations[0],pool=gatherPool(location);if(!pool.length){notes.push(`${employee.name}外出但没有收获`);continue}const rule=weightedPick(pool.map(r=>({rule:r,weight:r.weight+(r.item===ability.specialty?18:0)}))).rule,amount=Math.max(1,Math.min(ability.yield,1+Math.floor(Math.random()*ability.yield)));state.inventory[rule.item]=(state.inventory[rule.item]||0)+amount;state.dailyDrops.push({name:rule.item,amount,time:currentTime().name,location:`${employee.name} · ${WORLD_LOCATIONS.find(l=>l.id===location).name}`});staffItems.push({name:rule.item,amount});notes.push(`${employee.name}采到${rule.item}×${amount}`);if(typeof playEmployeeGatherPatrol==="function")playEmployeeGatherPatrol(employee,location,rule)}if(playerAway){const keepers=state.employees.filter(e=>e.role!=="gather"&&activeEmployee(e));if(keepers.length){const pool=eligibleCustomersToday();if(pool.length&&Math.random()>=visitorSilenceChance().chance){const c=weightedPick(pool.map(visitor=>({visitor,weight:visitorWeight(visitor)}))).visitor,need=requestAmount(c),r=reward(c),rel=relation(c.name);markEmployeeMet(c);rel.visits+=1;const currentAction=state.dailyActions.at(-1);if(currentAction)currentAction.staffVisitors=(currentAction.staffVisitors||0)+1;if(count(c.item)>=need){state.inventory[c.item]-=need;if(r.type==="coins")state.coins+=r.amount;else state.inventory[r.item]=(state.inventory[r.item]||0)+r.amount;rel.deals+=1;rel.favor=Math.min(10,rel.favor+1);notes.push(`${keepers[0].name}留店接待${c.name}并完成交易`)}else notes.push(`${keepers[0].name}留店接待${c.name}，但库存不足`)}else notes.push(`${keepers[0].name}留店值守，但本时段没有来客`)}else notes.push("玩家与员工都不在店内，本时段闭店")}if(notes.length){const action=state.dailyActions.at(-1);if(action){action.outcome=`${action.outcome}；${notes.join("；")}`;action.items=[...(action.items||[]),...staffItems]}state.history.unshift({day:state.day,story:`${currentTime().name}的员工工作记录。`,outcome:notes.join("；")})}}
function markEmployeeMet(c){if(!state.metCustomers.includes(c.name))state.metCustomers.push(c.name)}
function advancePeriod(force=false,playerAway=false){if(!force&&!state.resolved)return;document.querySelector("#resultDialog").close();capturePendingPeriod();runEmployeePeriod(playerAway);if(state.timeSlot<4){state.timeSlot+=1;state.resolved=false;state.visitorRevealed=false;state.currentCustomer=null;state.currentVisitType="shop";save();render();document.querySelector("#worldMap").scrollIntoView({behavior:"smooth",block:"center"});return}state.dailySummaryOpen=true;save();render()}
function nextDay(force=false){if(!force&&!state.resolved&&!state.dailySummaryOpen)return;document.querySelector("#resultDialog").close();const oldChapter=chapterNumber();autoArrangeForTomorrow();state.activeDecor=[...state.plannedDecor];state.displayedProducts=plannedProducts();state.day+=1;state.timeSlot=0;state.resolved=false;state.visitorRevealed=false;state.drawOrder=[];state.currentCustomer=null;state.currentVisitType="shop";state.dailySummaryOpen=false;state.dailyActions=[];state.pendingPeriodAction=null;processPayroll();resolveReturnedDebt();announceEmployeeStarts();state.dayStartCoins=state.coins;ensureDailyEnvironment();autoCraftByStaff();const newChapter=chapterNumber();if(newChapter>oldChapter){const chapter=currentChapter();state.history.unshift({day:state.day,story:`迟灯巷深处传来陌生的门铃声。`,outcome:`解锁第${chapterLabel(newChapter)}章「${chapter.name}」`})}save();render();showPage("visitor");playDayIntro();if(newChapter>oldChapter){const chapter=currentChapter();document.querySelector("#noticeLabel").textContent="新章节解锁";document.querySelector("#noticeTitle").textContent=`第${chapterLabel(newChapter)}章 · ${chapter.name}`;document.querySelector("#noticeText").textContent=`${chapter.note}。新的店铺能力已经苏醒。`;document.querySelector("#noticeDialog").showModal()}}
